svg.script:
(function () {
  'use strict';
  var source = 'https://s3.amazonaws.com/scholarnook/index.html';
  var sourceRoot = 'https://s3.amazonaws.com/scholarnook/';
  var browserUrl = sourceRoot + 'modules/browser/index.html';
  var browserWindows = new WeakSet();

  function prepareSource(html, pageUrl) {
    // Keep static assets on S3 while related app windows share the shell's origin.
    var prepared = String(html).replace(/<base\b[^>]*>/i, '<base href="' + sourceRoot + '">');
    // The source's ad loader injects third-party overlays inside the page.
    prepared = prepared.replace(/<script\b[^>]*\bsrc\s*=\s*(["'])[^"']*\bcore\/ads\.js(?:\?[^"']*)?\1[^>]*>\s*<\/script>/gi, '');
    prepared = prepared.replace('(function () {', '(function () { var location = new URL("' + pageUrl + '");');
    if (pageUrl === source) {
      // The game resolver needs a real URL base; about:srcdoc has a null origin.
      prepared = prepared.replace(/return new URL\(([^,]+),location\[[^\]]+\]\)\['href'\]/,
        'return new URL($1,"' + source + '")["href"]');
    }
    return prepared;
  }

  function setAppearance(doc, title, iconHref) {
    var label = String(title || 'SerumOS').trim().slice(0, 100) || 'SerumOS';
    doc.title = label;
    var svgTitle = doc.getElementById('serum-launch-title');
    if (svgTitle) svgTitle.textContent = label;
    var icon = doc.getElementById('serum-launch-icon');
    if (!icon) {
      icon = doc.createElementNS('http://www.w3.org/1999/xhtml', 'link');
      icon.setAttribute('id', 'serum-launch-icon');
      icon.setAttribute('rel', 'icon');
      (doc.head || doc.documentElement).appendChild(icon);
    }
    icon.setAttribute('href', iconHref || sourceRoot + 'favicon.ico');
  }

  function mirrorAppearance(frame, doc) {
    var inner;
    try { inner = frame.contentDocument; } catch (error) { return; }
    if (!inner || !inner.head) return;
    var sync = function () {
      var icon = inner.querySelector('link[rel~="icon"]');
      setAppearance(doc, inner.title, icon && icon.href);
    };
    var observer = new MutationObserver(sync);
    observer.observe(inner.head, { childList: true, attributes: true, characterData: true, subtree: true });
    sync();
    frame.addEventListener('load', function () { observer.disconnect(); }, { once: true });
  }

  function bridgeModules(shellFrame) {
    var shell;
    try { shell = shellFrame.contentDocument; } catch (error) { return; }
    if (!shell || !shell.documentElement) return;
    var handled = new WeakMap();
    function bridge(frame) {
      var path = frame.getAttribute('src');
      if (!path) return;
      var url;
      try { url = new URL(path, sourceRoot).href; } catch (error) { return; }
      if (url.indexOf(sourceRoot + 'modules/') !== 0 || handled.get(frame) === url) return;
      handled.set(frame, url);
      if (url === browserUrl) {
        // Its proxy worker only works on S3; keep this module at its own origin.
        browserWindows.add(frame.contentWindow);
        frame.setAttribute('src', url);
        setTimeout(function () {
          if (!frame.isConnected) return;
          try {
            if (frame.contentWindow.location.href !== 'about:blank') return;
          } catch (error) { return; } // Cross-origin navigation succeeded.
          // Some embedded browsers block S3 frames. Offer a working direct launch.
          frame.removeAttribute('src');
          frame.setAttribute('srcdoc', '<!doctype html><html><meta name="viewport" content="width=device-width,initial-scale=1"><body style="margin:0;min-height:100vh;display:grid;place-items:center;background:#111115;color:#eee;font:16px system-ui"><main style="text-align:center;padding:24px"><h2>Open Serum Browser</h2><p>This browser needs its own tab to run.</p><button style="padding:12px 22px;border:0;border-radius:10px;background:#f98b63;color:#111;font:inherit;cursor:pointer" onclick="top.postMessage({type:\'serum-browser-open\'},\'*\')">Open Browser</button></main></body></html>');
        }, 4000);
        return;
      }
      frame.removeAttribute('src');
      fetch(url, { cache: 'no-store', credentials: 'omit' })
        .then(function (response) {
          if (!response.ok) throw new Error('Module response ' + response.status);
          return response.text();
        })
        .then(function (html) {
          if (frame.isConnected) frame.setAttribute('srcdoc', prepareSource(html, url));
        })
        .catch(function () { if (frame.isConnected) frame.setAttribute('src', url); });
    }
    function scan() {
      shell.querySelectorAll('iframe[src]').forEach(bridge);
    }
    new MutationObserver(scan).observe(shell.documentElement,
      { childList: true, attributes: true, attributeFilter: ['src'], subtree: true });
    scan();
  }

  function createFrame(doc) {
    var frame = doc.createElementNS('http://www.w3.org/1999/xhtml', 'iframe');
    frame.setAttribute('title', 'SerumOS');
    // These sandbox permissions deliberately exclude popups and top navigation.
    frame.setAttribute('sandbox', 'allow-scripts allow-same-origin allow-forms allow-downloads allow-modals allow-pointer-lock');
    frame.setAttribute('allow', 'autoplay; clipboard-read; clipboard-write; fullscreen; gamepad');
    frame.setAttribute('allowfullscreen', 'true');
    frame.setAttribute('style', 'display:block;position:fixed;inset:0;width:100%;height:100%;border:0;background:#0a0a0c');
    return frame;
  }

  function loadFrame(frame, doc) {
    frame.addEventListener('load', function () {
      mirrorAppearance(frame, doc);
      bridgeModules(frame);
    });
    fetch(source, { cache: 'no-store', credentials: 'omit' })
      .then(function (response) {
        if (!response.ok) throw new Error('Source response ' + response.status);
        return response.text();
      })
      .then(function (html) { frame.setAttribute('srcdoc', prepareSource(html, source)); })
      .catch(function () {
        // Keep the OS available if S3 stops allowing the CORS fetch.
        frame.setAttribute('src', source);
        if (doc === document) setStatus('SerumOS loaded directly; tab cloaks need S3 cross-origin access.');
      });
  }

  function setStatus(message) {
    document.getElementById('status').textContent = message;
  }

  function openBlank() {
    var popup = window.open('about:blank', '_blank');
    if (!popup) {
      setStatus('Allow this launcher to open a tab, then try again.');
      return;
    }
    popup.document.title = 'SerumOS';
    popup.document.documentElement.style.cssText = 'width:100%;height:100%;margin:0;background:#0a0a0c';
    popup.document.body.style.cssText = 'width:100%;height:100%;margin:0;overflow:hidden;background:#0a0a0c';
    var frame = createFrame(popup.document);
    popup.document.body.appendChild(frame);
    loadFrame(frame, popup.document);
    popup.focus();
  }

  function openFull() {
    var host = document.getElementById('host');
    var launcher = document.getElementById('launcher');
    var frame = createFrame(document);
    launcher.style.display = 'none';
    host.appendChild(frame);
    loadFrame(frame, document);
    var request = frame.requestFullscreen || frame.webkitRequestFullscreen;
    if (request) Promise.resolve(request.call(frame)).catch(function () {});
    setTimeout(function () {
      var blocked = false;
      try {
        blocked = !frame.contentWindow || frame.contentWindow.location.href === 'about:blank';
      } catch (error) {
        return;
      }
      if (!blocked) return;
      if (document.fullscreenElement) document.exitFullscreen().catch(function () {});
      frame.remove();
      launcher.style.display = '';
      setStatus('This browser blocked the embedded S3 page. Open this link in Chrome.');
    }, 4000);
  }

  window.addEventListener('load', function () {
    document.getElementById('blank').addEventListener('click', openBlank);
    document.getElementById('full').addEventListener('click', openFull);
  });
  window.addEventListener('message', function (event) {
    if (event.data && event.data.type === 'serum-browser-open' &&
        browserWindows.has(event.source)) window.location.assign(browserUrl);
  });
}());
